const fs = require('fs');
const path = require('path');
const ROOT = path.resolve(__dirname, '../..');

function bundleParent() {
    const banner = `/* ==========================================================================
   ⚠️ AUTOGENERATED RUNTIME BUNDLE - DO NOT EDIT DIRECTLY!
   Source Directory: js/parent/modules/
   Mọi chỉnh sửa trực tiếp vào tệp này sẽ bị ghi đè khi chạy build.
   ========================================================================== */\n\n`;

    const modules = [
        'js/parent/modules/auth.controller.js',
        'js/parent/modules/chart.renderer.js',
        'js/parent/modules/student.manager.js',
        'js/parent/modules/history.viewer.js',
        'js/parent/modules/remote.sync.js',
        'js/parent/index.js'
    ];

    let bundle = banner;
    modules.forEach(m => {
        const full = path.join(ROOT, m);
        if (fs.existsSync(full)) {
            bundle += `// --- Module: ${m} ---\n` + fs.readFileSync(full, 'utf8') + '\n\n';
        }
    });

    fs.writeFileSync(path.join(ROOT, 'js/parent.js'), bundle, 'utf8');
    console.log(`✅ Đã đóng gói thành công js/parent.js (${bundle.split('\n').length} dòng).`);
}

if (require.main === module) bundleParent();
module.exports = bundleParent;
